"""Glossary: term id -> {term, en, hi, hinglish}. Lessons reference terms as {{id|label}}; the UI turns them into clickable definitions."""


def g(term, en, hi, hinglish):
    return {"term": term, "en": en, "hi": hi, "hinglish": hinglish}


GLOSSARY = {
    "ai": g("AI", "Software that does tasks that normally need human intelligence, like understanding language or recognising pictures.", "ऐसा software जो वो काम करता है जिनके लिए आम तौर पर इंसान की समझ चाहिए, जैसे भाषा समझना या तस्वीर पहचानना।", "AI aisa software hai jo woh kaam karta hai jinke liye normally insaan ki samajh chahiye, jaise language samajhna ya picture pehchanna."),
    "ml": g("Machine Learning", "A way to build software by showing it many examples so it learns the pattern, instead of writing every rule by hand.", "Software बनाने का तरीका जिसमें हम उसे बहुत सारे examples दिखाते हैं और वो खुद pattern सीखता है, हर rule हाथ से लिखने की जगह।", "Machine Learning mein hum software ko bahut saare examples dikhate hain aur woh khud pattern seekhta hai, har rule haath se likhne ki jagah."),
    "dl": g("Deep Learning", "Machine learning that uses neural networks with many layers. It is what powers modern language and image models.", "Machine learning का वो हिस्सा जो कई layers वाले neural networks इस्तेमाल करता है। आज के language और image models इसी से चलते हैं।", "Deep Learning, machine learning ka hissa hai jisme bahut saari layers wale neural networks use hote hain. Aaj ke language aur image models isi se chalte hain."),
    "neural-network": g("Neural network", "A large collection of simple number-crunching units, arranged in layers, whose connection strengths are learned from data.", "सरल calculation करने वाली छोटी units का बड़ा समूह, layers में सजा हुआ, जिनकी connection strength data से सीखी जाती है।", "Neural network chhoti calculation units ka bada group hai, layers mein arranged, jinki connection strength data se seekhi jaati hai."),
    "llm": g("LLM", "Large Language Model: a neural network trained on huge amounts of text that predicts the next token, one after another, to write text.", "Large Language Model: बहुत सारे text पर train किया गया neural network जो अगला token predict करके एक-एक करके text लिखता है।", "LLM (Large Language Model) bahut saare text par train hua neural network hai jo agla token predict karke ek ek karke text likhta hai."),
    "token": g("Token", "A small piece of text (a word, part of a word or a symbol) that a model reads and writes. Models count length in tokens, not words.", "text का छोटा हिस्सा (शब्द, शब्द का टुकड़ा या symbol) जिसे model पढ़ता और लिखता है। Model लंबाई tokens में गिनता है, words में नहीं।", "Token text ka chhota tukda hai (word, word ka part ya symbol) jise model padhta aur likhta hai. Model length tokens mein ginta hai, words mein nahi."),
    "context-window": g("Context window", "The maximum number of tokens a model can look at in one request: your prompt, the documents you add, and its own answer.", "एक request में model अधिकतम कितने tokens देख सकता है: आपका prompt, जोड़े गए documents और उसका अपना जवाब।", "Context window woh maximum tokens hain jo model ek request mein dekh sakta hai: aapka prompt, add kiye documents aur uska apna answer."),
    "transformer": g("Transformer", "The neural-network design behind modern LLMs. Its key idea is attention: every token can look at every other token to decide what matters.", "आज के LLMs के पीछे की neural-network design। इसका मुख्य idea attention है: हर token बाकी tokens को देखकर तय करता है कि क्या ज़रूरी है।", "Transformer woh design hai jo aaj ke LLMs ke peeche hai. Iska main idea attention hai: har token baaki tokens ko dekhkar decide karta hai kya zaroori hai."),
    "attention": g("Attention", "A step where each token scores how relevant every other token is and mixes in information from the relevant ones.", "एक step जिसमें हर token बाकी tokens को relevance के हिसाब से score देता है और काम के tokens से जानकारी लेता है।", "Attention woh step hai jisme har token baaki tokens ko relevance ke hisaab se score deta hai aur kaam ke tokens se information leta hai."),
    "temperature": g("Temperature", "A setting that controls randomness. Low = predictable, focused answers. High = more varied, creative (and riskier) answers.", "Randomness control करने वाली setting। कम = predictable और focused जवाब। ज़्यादा = ज़्यादा अलग, creative (और risky) जवाब।", "Temperature randomness control karti hai. Low = predictable, focused answers. High = zyada varied, creative (aur risky) answers."),
    "sampling": g("Sampling", "Choosing the next token from the model's probabilities, for example the single most likely one, or a random pick among the top few.", "Model की probabilities में से अगला token चुनना, जैसे सबसे ज़्यादा संभावित, या top कुछ में से random।", "Sampling matlab model ki probabilities mein se agla token chunna, jaise sabse likely wala ya top kuch mein se random."),
    "prompt": g("Prompt", "The input you give a model: instructions, context and the question.", "Model को दिया गया input: instructions, context और सवाल।", "Prompt woh input hai jo aap model ko dete ho: instructions, context aur question."),
    "system-prompt": g("System prompt", "Standing instructions that set the model's role and rules for the whole conversation.", "पूरी बातचीत के लिए model का role और rules तय करने वाले standing instructions।", "System prompt standing instructions hain jo poori conversation ke liye model ka role aur rules set karte hain."),
    "few-shot": g("Few-shot prompting", "Putting a few worked examples inside the prompt so the model copies the pattern.", "Prompt में कुछ solved examples डालना ताकि model वही pattern follow करे।", "Few-shot prompting mein prompt ke andar kuch solved examples daalte hain taaki model wahi pattern follow kare."),
    "hallucination": g("Hallucination", "When a model states something false or invented in a confident tone.", "जब model पूरे confidence से कोई गलत या बनाई हुई बात बोल देता है।", "Hallucination tab hoti hai jab model pure confidence se koi galat ya banayi hui baat bol deta hai."),
    "embedding": g("Embedding", "A list of numbers (a vector) that represents the meaning of a text. Texts with similar meaning get nearby vectors.", "Numbers की list (vector) जो text का मतलब represent करती है। मिलते-जुलते मतलब वाले texts के vectors पास-पास होते हैं।", "Embedding numbers ki list (vector) hai jo text ka meaning represent karti hai. Milte-julte meaning wale texts ke vectors paas paas hote hain."),
    "vector": g("Vector", "An ordered list of numbers. In AI, a point in a space with hundreds or thousands of dimensions.", "numbers की क्रम में लिखी list। AI में, सैकड़ों या हज़ारों dimensions वाली space का एक point।", "Vector numbers ki ordered list hai. AI mein, sainkdon ya hazaron dimensions wali space ka ek point."),
    "cosine-similarity": g("Cosine similarity", "A score from -1 to 1 for how much two vectors point in the same direction. Closer to 1 means more similar meaning.", "-1 से 1 तक का score कि दो vectors कितना एक ही direction में हैं। 1 के पास = ज़्यादा मिलता-जुलता मतलब।", "Cosine similarity -1 se 1 ka score hai ki do vectors kitne same direction mein hain. 1 ke paas matlab zyada similar meaning."),
    "vector-db": g("Vector database", "A store built to find the vectors closest to a query vector quickly, even among millions.", "ऐसा store जो लाखों vectors में से query vector के सबसे पास वाले vectors जल्दी ढूंढता है।", "Vector database aisa store hai jo lakhon vectors mein se query vector ke sabse paas wale vectors jaldi dhundhta hai."),
    "ann": g("ANN search", "Approximate nearest neighbour search: finds very close vectors much faster than checking all of them, by accepting a tiny chance of missing the exact best one.", "Approximate nearest neighbour search: सारे vectors चेक करने से बहुत तेज़ी से पास वाले vectors ढूंढता है, बदले में exact best छूट जाने की छोटी संभावना होती है।", "ANN search sabhi vectors check kiye bina bahut tez nearest vectors dhundhta hai; badle mein exact best miss hone ka chhota chance hota hai."),
    "semantic-search": g("Semantic search", "Search by meaning rather than exact words, using embeddings.", "exact शब्दों की जगह मतलब के आधार पर search, embeddings की मदद से।", "Semantic search exact words ki jagah meaning ke basis par search hai, embeddings ki madad se."),
    "rag": g("RAG", "Retrieval-Augmented Generation: first search your documents for relevant passages, then give them to the model so it answers from them.", "Retrieval-Augmented Generation: पहले documents में से काम के हिस्से खोजो, फिर उन्हें model को दो ताकि वो उन्हीं से जवाब दे।", "RAG (Retrieval-Augmented Generation) mein pehle documents mein se relevant parts dhundhte hain, phir model ko dete hain taaki woh unhi se answer kare."),
    "chunk": g("Chunk", "A piece of a document (for example 1000 characters) that is embedded and retrieved on its own.", "Document का एक टुकड़ा (जैसे 1000 characters) जिसे अलग से embed और retrieve किया जाता है।", "Chunk document ka ek tukda hai (jaise 1000 characters) jise alag se embed aur retrieve kiya jaata hai."),
    "retriever": g("Retriever", "The part that, given a question, returns the most relevant chunks.", "वो हिस्सा जो सवाल मिलने पर सबसे relevant chunks लौटाता है।", "Retriever woh part hai jo question milne par sabse relevant chunks return karta hai."),
    "reranker": g("Reranker", "A second, more careful model that re-orders the retrieved chunks so the best ones come first.", "दूसरा, ज़्यादा ध्यान से देखने वाला model जो मिले हुए chunks को दोबारा क्रम देता है ताकि सबसे अच्छे ऊपर आएँ।", "Reranker doosra, zyada dhyan se dekhne wala model hai jo mile hue chunks ko dobara order karta hai taaki best upar aayein."),
    "cross-encoder": g("Cross-encoder", "A reranker that reads the question and a chunk together and outputs one relevance score. More accurate but slower than comparing embeddings.", "Reranker जो सवाल और chunk को साथ में पढ़कर एक relevance score देता है। Embeddings की तुलना से ज़्यादा सटीक पर धीमा।", "Cross-encoder reranker hai jo question aur chunk ko saath padhkar ek relevance score deta hai. Embeddings compare karne se zyada accurate par slow."),
    "hybrid-search": g("Hybrid search", "Combining keyword search (exact words) with vector search (meaning) and merging the two rankings.", "Keyword search (exact शब्द) और vector search (मतलब) को मिलाकर दोनों की ranking merge करना।", "Hybrid search mein keyword search (exact words) aur vector search (meaning) ko milakar dono ki ranking merge karte hain."),
    "bm25": g("BM25", "A classic keyword-ranking formula: rare words that appear often in a document score higher.", "Keyword ranking का classic formula: document में बार-बार आने वाले दुर्लभ शब्दों को ज़्यादा score मिलता है।", "BM25 classic keyword-ranking formula hai: jo rare words document mein baar baar aate hain unhe zyada score milta hai."),
    "rrf": g("Reciprocal Rank Fusion", "A simple way to merge rankings: each result gets 1/(60+rank) from every list; sum the points.", "Rankings merge करने का आसान तरीका: हर list से result को 1/(60+rank) मिलता है; points जोड़ दो।", "Reciprocal Rank Fusion rankings merge karne ka simple tareeka hai: har list se result ko 1/(60+rank) milta hai; points jod do."),
    "hyde": g("HyDE", "Hypothetical Document Embeddings: ask the model to write a fake answer, then search with that text because it looks more like real documents than the question does.", "Hypothetical Document Embeddings: model से एक नकली जवाब लिखवाओ और उसी text से search करो, क्योंकि वो असली documents जैसा दिखता है।", "HyDE mein model se ek fake answer likhwate hain aur usi text se search karte hain, kyunki woh question se zyada real documents jaisa lagta hai."),
    "multi-query": g("Multi-query retrieval", "Rewriting one question several ways, searching with each, and merging the results to catch more relevant chunks.", "एक सवाल को कई तरह से लिखकर हर एक से search करना और results merge करना ताकि ज़्यादा relevant chunks मिलें।", "Multi-query retrieval mein ek question ko kai tarah se likhkar har ek se search karte hain aur results merge karte hain."),
    "lcel": g("LCEL", "LangChain Expression Language: connect components with the | operator, like prompt | model | parser.", "LangChain Expression Language: components को | operator से जोड़ना, जैसे prompt | model | parser।", "LCEL (LangChain Expression Language) mein components ko | operator se jodte hain, jaise prompt | model | parser."),
    "runnable": g("Runnable", "LangChain's common interface: anything with invoke, batch and stream, so parts can be chained.", "LangChain का common interface: जिसमें invoke, batch और stream हों, ताकि हिस्से आपस में जुड़ सकें।", "Runnable LangChain ka common interface hai: jisme invoke, batch aur stream hote hain, taaki parts chain ho sakein."),
    "output-parser": g("Output parser", "Turns the model's text into something your code can use, like a string, a list or a typed object.", "Model के text को ऐसी चीज़ में बदलता है जिसे आपका code इस्तेमाल कर सके, जैसे string, list या typed object।", "Output parser model ke text ko aisi cheez mein badalta hai jo aapka code use kar sake, jaise string, list ya typed object."),
    "structured-output": g("Structured output", "Making the model return data in a fixed shape (like JSON matching a schema) instead of free text.", "Model से fixed shape में data (जैसे schema से मेल खाता JSON) लेना, free text की जगह।", "Structured output mein model se fixed shape mein data (jaise schema wala JSON) lete hain, free text ki jagah."),
    "tool-calling": g("Tool calling", "The model asks your code to run a named function with arguments; your code runs it and returns the result.", "Model आपके code से किसी नाम वाले function को arguments के साथ चलाने को कहता है; code उसे चलाकर result लौटाता है।", "Tool calling mein model aapke code se ek named function arguments ke saath chalane ko kehta hai; code use chalakar result wapas deta hai."),
    "langgraph": g("LangGraph", "A library for building workflows as a graph of steps that share a state, with branches, loops, memory and human approval.", "Workflows को steps के graph की तरह बनाने की library, जिनके बीच state share होती है, साथ में branches, loops, memory और human approval।", "LangGraph workflows ko steps ke graph ki tarah banane ki library hai, jinke beech state share hoti hai, branches, loops, memory aur human approval ke saath."),
    "state": g("State", "The shared data every step of a graph reads and updates, like a notebook passed from step to step.", "वो shared data जिसे graph का हर step पढ़ता और update करता है, जैसे एक notebook जो step से step तक जाती है।", "State woh shared data hai jise graph ka har step padhta aur update karta hai, jaise ek notebook jo step se step jaati hai."),
    "node": g("Node", "One step in a graph: a function that reads the state and returns changes to it.", "Graph का एक step: एक function जो state पढ़ता है और उसमें बदलाव लौटाता है।", "Node graph ka ek step hai: ek function jo state padhta hai aur usme changes return karta hai."),
    "conditional-edge": g("Conditional edge", "A connection whose destination is chosen at run time by a function that looks at the state.", "ऐसा connection जिसकी destination run time पर एक function state देखकर चुनता है।", "Conditional edge aisa connection hai jiski destination run time par ek function state dekhkar chunta hai."),
    "checkpoint": g("Checkpoint", "A saved snapshot of the graph state after a step, so a run can be resumed, inspected or replayed.", "किसी step के बाद graph state का saved snapshot, ताकि run को resume, inspect या replay किया जा सके।", "Checkpoint kisi step ke baad graph state ka saved snapshot hai, taaki run resume, inspect ya replay ho sake."),
    "hitl": g("Human-in-the-loop", "Pausing a workflow so a person can approve, edit or reject before it continues.", "Workflow को रोकना ताकि कोई इंसान आगे बढ़ने से पहले approve, edit या reject कर सके।", "Human-in-the-loop mein workflow ko pause karte hain taaki koi insaan aage badhne se pehle approve, edit ya reject kar sake."),
    "agent": g("AI agent", "A system where a model decides which steps and tools to use to reach a goal, repeating until it is done.", "ऐसा system जहाँ model तय करता है कि लक्ष्य तक पहुँचने के लिए कौन से steps और tools इस्तेमाल करने हैं, और पूरा होने तक दोहराता है।", "AI agent aisa system hai jahan model decide karta hai ki goal tak pahunchne ke liye kaunse steps aur tools use karne hain, aur done hone tak repeat karta hai."),
    "react-pattern": g("ReAct loop", "The agent loop: think about the next action, act (call a tool), observe the result, and repeat.", "Agent loop: अगला action सोचो, act करो (tool call), result observe करो, और दोहराओ।", "ReAct loop: agla action socho, act karo (tool call), result observe karo, aur repeat karo."),
    "reflection": g("Reflection", "A step where the agent (or a second model) checks its own result and decides to accept it or try again.", "एक step जहाँ agent (या दूसरा model) अपने result को जाँचकर तय करता है कि उसे मानना है या दोबारा कोशिश करनी है।", "Reflection mein agent (ya doosra model) apne result ko check karke decide karta hai ki accept karna hai ya dobara try karna hai."),
    "supervisor": g("Supervisor agent", "An agent whose job is to decide which specialist agent should work next, and when the task is finished.", "ऐसा agent जिसका काम तय करना है कि अगला काम कौन सा specialist agent करेगा, और task कब पूरा हुआ।", "Supervisor agent ka kaam decide karna hai ki agla kaam kaunsa specialist agent karega, aur task kab complete hua."),
    "mcp": g("MCP", "Model Context Protocol: an open standard that lets an AI application discover and use tools, data and prompts offered by separate servers.", "Model Context Protocol: एक open standard जिससे AI application अलग servers द्वारा दिए गए tools, data और prompts खोजकर इस्तेमाल कर सकती है।", "MCP (Model Context Protocol) ek open standard hai jisse AI application alag servers ke diye tools, data aur prompts discover karke use kar sakti hai."),
    "evaluation": g("Evaluation", "Measuring answer quality with a fixed set of test questions so you can tell whether a change helped.", "Test सवालों के fixed set से answer quality नापना ताकि पता चले कि कोई बदलाव फायदेमंद था या नहीं।", "Evaluation mein test questions ke fixed set se answer quality napte hain taaki pata chale koi change fayde ka tha ya nahi."),
    "faithfulness": g("Faithfulness", "Whether every claim in an answer is supported by the retrieved sources.", "क्या जवाब की हर बात retrieved sources से समर्थित है।", "Faithfulness ka matlab: answer ki har baat retrieved sources se supported hai ya nahi."),
    "recall-at-k": g("Recall@k", "Of all the chunks that should be found, the share that appear in the top k results.", "जितने chunks मिलने चाहिए थे, उनमें से कितने top k results में आए।", "Recall@k: jitne chunks milne chahiye the unmein se kitne top k results mein aaye."),
    "streaming": g("Streaming", "Sending the answer to the user piece by piece as it is generated instead of waiting for the whole answer.", "जवाब पूरा बनने का इंतज़ार किए बिना, बनते-बनते टुकड़ों में user को भेजना।", "Streaming mein answer poora banne ka wait kiye bina, banate banate tukdon mein user ko bhejte hain."),
    "sse": g("Server-Sent Events", "A simple web standard where the server keeps one HTTP response open and pushes text events to the browser.", "एक सरल web standard जिसमें server एक HTTP response खुला रखकर browser को text events भेजता रहता है।", "Server-Sent Events ek simple web standard hai jisme server ek HTTP response khula rakhkar browser ko text events bhejta rehta hai."),
    "prompt-injection": g("Prompt injection", "Text inside a document or web page that tries to give the model new orders. Treat retrieved text as data, never as instructions.", "किसी document या web page के अंदर लिखा text जो model को नए आदेश देने की कोशिश करता है। Retrieved text को data मानो, instruction नहीं।", "Prompt injection document ya web page ke andar likha text hai jo model ko naye orders dene ki koshish karta hai. Retrieved text ko data maano, instruction nahi."),
    "observability": g("Observability", "Logs, metrics and traces that let you see what your system did and why.", "Logs, metrics और traces जिनसे आप देख सकते हैं कि system ने क्या किया और क्यों।", "Observability matlab logs, metrics aur traces jinse aap dekh sakte ho system ne kya kiya aur kyun."),
    "latency": g("Latency", "How long a request takes. For streaming chat, the important number is the time until the first token.", "एक request में कितना समय लगता है। Streaming chat में ज़रूरी number पहले token तक का समय है।", "Latency matlab request mein kitna time lagta hai. Streaming chat mein important number pehle token tak ka time hai."),
}
